/// <summary>
/// Tools available to the research agent for web searching and note-taking.
/// </summary>
public sealed class ResearchTools
{
    private readonly List<string> _notes = [];
    private readonly HttpClient _httpClient = new();

    [Description("Search the web for information on a query. Returns search results with titles, snippets, and URLs.")]
    public async Task<string> SearchWeb(
        [Description("The search query to look up")] string query)
    {
        Console.WriteLine($"  [Tool] Searching web: \"{query}\"");

        try
        {
            var encoded = Uri.EscapeDataString(query);
            var request = new HttpRequestMessage(HttpMethod.Get,
                $"https://html.duckduckgo.com/html/?q={encoded}");
            request.Headers.UserAgent.ParseAdd("ResearchAgent/1.0");

            var response = await _httpClient.SendAsync(request);
            var html = await response.Content.ReadAsStringAsync();

            var results = ParseSearchResults(html);
            return results.Length > 0
                ? results
                : $"No results found for '{query}'. Try a different search query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try again with a different query.";
        }
    }

    [Description("Take a note to remember an important finding during research.")]
    public string TakeNote(
        [Description("The note content to save")] string note,
        [Description("The source URL or reference for this note")] string source)
    {
        Console.WriteLine($"  [Tool] Taking note from: {source}");
        _notes.Add($"- {note} (Source: {source})");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all notes taken so far during research.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes taken yet.";

        return $"Research notes ({_notes.Count} total):\n{string.Join("\n", _notes)}";
    }

    public void ClearNotes() => _notes.Clear();

    private static string ParseSearchResults(string html)
    {
        var results = new List<string>();
        var searchIndex = 0;
        const string snippetMarker = "result__snippet";

        for (int i = 0; i < 5; i++)
        {
            var idx = html.IndexOf(snippetMarker, searchIndex, StringComparison.Ordinal);
            if (idx < 0) break;

            const string titleMarker = "result__a";
            var titleIdx = html.LastIndexOf(titleMarker, idx, StringComparison.Ordinal);

            var title = titleIdx >= 0 ? ExtractTagContent(html, titleIdx) : "Untitled";
            var snippet = ExtractTagContent(html, idx);
            var url = ExtractHref(html, titleIdx >= 0 ? titleIdx : idx);

            if (!string.IsNullOrWhiteSpace(snippet))
            {
                results.Add($"[{i + 1}] {title}\n    {snippet}\n    URL: {url}");
            }

            searchIndex = idx + snippetMarker.Length;
        }

        return string.Join("\n\n", results);
    }

    private static string ExtractTagContent(string html, int startFrom)
    {
        var gt = html.IndexOf('>', startFrom);
        if (gt < 0) return "";
        var lt = html.IndexOf('<', gt);
        if (lt < 0) return "";
        var content = html[(gt + 1)..lt].Trim();
        return System.Net.WebUtility.HtmlDecode(content);
    }

    private static string ExtractHref(string html, int startFrom)
    {
        var hrefIdx = html.IndexOf("href=\"", startFrom, StringComparison.Ordinal);
        if (hrefIdx < 0) return "unknown";
        var start = hrefIdx + 6;
        var end = html.IndexOf('"', start);
        if (end < 0) return "unknown";
        var url = html[start..end];
        return System.Net.WebUtility.HtmlDecode(url);
    }
}

