using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using System.ComponentModel;
using System.Text.Json;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set AI:ApiKey in config or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClient(apiKey)));

builder.Services.AddSingleton<ResearchTools>();

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var researchTools = host.Services.GetRequiredService<ResearchTools>();

var agent = new ChatClientAgent(chatClient,
    "ResearchAgent",
    """
    You are a research assistant. Your job is to research a topic thoroughly by
    searching the web for relevant information, taking notes on key findings,
    and then producing a concise summary. Follow this workflow:
    1. Search the web for information on the given topic (multiple searches if needed).
    2. Take notes on the most important findings from each search.
    3. After gathering enough information, produce a final summary.
    Always cite your sources.
    """)
{
    Tools = [
        AIFunctionFactory.Create(researchTools.SearchWeb),
        AIFunctionFactory.Create(researchTools.TakeNote),
        AIFunctionFactory.Create(researchTools.GetNotes),
    ]
};

Console.WriteLine("=== Research Agent ===");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):");
Console.Write("> ");

while (Console.ReadLine() is { } input && !input.Equals("quit", StringComparison.OrdinalIgnoreCase))
{
    if (string.IsNullOrWhiteSpace(input))
    {
        Console.Write("> ");
        continue;
    }

    researchTools.ClearNotes();

    var history = new List<ChatMessage>
    {
        new(ChatRole.User, $"Research the following topic and provide a summary: {input}")
    };

    var options = new AgentInvokeOptions
    {
        MaximumIterations = 10,
    };

    Console.WriteLine($"\nResearching: {input}\n");

    await foreach (var message in agent.InvokeStreamingAsync(history, options))
    {
        if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
        {
            Console.Write(message.Text);
        }
    }

    Console.WriteLine("\n");
    Console.Write("> ");
}

Console.WriteLine("Goodbye!");

